```json
{
  "root_causes": [
    {
      "service": "reservation",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'normal' period, count(*) reservation_spans, max(time) last_seen FROM normal_traces WHERE service_name='reservation' UNION ALL SELECT 'abnormal', count(*), max(time) FROM abnormal_traces WHERE service_name='reservation'",
          "claim": "Reservation emitted 2193 spans in the normal period, last at 12:48:18, and zero spans in the entire abnormal period."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, count(*) n, round(avg(duration)/1e6,3) avg_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='reservation.Reservation/CheckAvailability' GROUP BY 1,2",
          "claim": "Frontend's CheckAvailability calls to reservation fail with Error status in about 0.017 ms, 945 times, consistent with a dead callee."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, left(message,220) msg, count(*) n, min(time) t0 FROM abnormal_logs WHERE level='ERROR' GROUP BY 1,2,3 ORDER BY n DESC LIMIT 15",
          "claim": "Frontend logged about 1,021 'Reservation check availability failed' errors starting 12:48:24, right after reservation went silent."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "reservation",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.span_name parent, c.service_name, c.span_name child, count(*) n FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='frontend' AND c.attr_span_kind='Client' GROUP BY 1,2,3 ORDER BY 1,2,3",
          "claim": "In abnormal /hotels traces, frontend calls reservation CheckAvailability 948 times, but profile GetProfiles only 3 times, versus 776 in normal."
        }
      ]
    }
  ]
}
```

